const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

function multiplyAv(n, input, output, start, end) {
  for (let i = start; i < end; i++) {
    let sum = 0.0;
    let denom = (i * (i + 1)) / 2 + i + 1;
    let inc = i + 1;

    for (let j = 0; j < n; j++) {
      sum += input[j] / denom;
      denom += inc;
      inc++;
    }

    output[i] = sum;
  }
}

function multiplyAtv(n, input, output, start, end) {
  for (let i = start; i < end; i++) {
    let sum = 0.0;
    let denom = (i * (i + 1)) / 2 + 1;
    let inc = i + 2;

    for (let j = 0; j < n; j++) {
      sum += input[j] / denom;
      denom += inc;
      inc++;
    }

    output[i] = sum;
  }
}

function multiplyAtAvSingle(n, input, output, tmp) {
  multiplyAv(n, input, tmp, 0, n);
  multiplyAtv(n, tmp, output, 0, n);
}

function runSingle(n) {
  const u = new Float64Array(n);
  const v = new Float64Array(n);
  const tmp = new Float64Array(n);

  u.fill(1.0);

  for (let i = 0; i < 10; i++) {
    multiplyAtAvSingle(n, u, v, tmp);
    multiplyAtAvSingle(n, v, u, tmp);
  }

  let vBv = 0.0;
  let vv = 0.0;

  for (let i = 0; i < n; i++) {
    vBv += u[i] * v[i];
    vv += v[i] * v[i];
  }

  return Math.sqrt(vBv / vv);
}

if (!isMainThread) {
  const n = workerData.n;
  const start = workerData.start;
  const end = workerData.end;

  const arrays = [
    new Float64Array(workerData.buffers[0]),
    new Float64Array(workerData.buffers[1]),
    new Float64Array(workerData.buffers[2])
  ];

  parentPort.on('message', (msg) => {
    const op = msg[0];
    const input = arrays[msg[1]];
    const output = arrays[msg[2]];

    if (op === 0) {
      multiplyAv(n, input, output, start, end);
    } else {
      multiplyAtv(n, input, output, start, end);
    }

    parentPort.postMessage(0);
  });
} else {
  const n = Number.parseInt(process.argv[2], 10);

  async function runParallel(n) {
    const os = require('os');
    const threadCount = Math.min(8, os.cpus().length, n);

    const sabU = new SharedArrayBuffer(Float64Array.BYTES_PER_ELEMENT * n);
    const sabV = new SharedArrayBuffer(Float64Array.BYTES_PER_ELEMENT * n);
    const sabTmp = new SharedArrayBuffer(Float64Array.BYTES_PER_ELEMENT * n);

    const u = new Float64Array(sabU);
    const v = new Float64Array(sabV);

    u.fill(1.0);

    const buffers = [sabU, sabV, sabTmp];
    const workers = [];
    const states = [];

    const chunk = Math.ceil(n / threadCount);

    for (let t = 0; t < threadCount; t++) {
      const start = t * chunk;
      const end = Math.min(n, start + chunk);
      if (start >= end) break;

      const state = { worker: null, done: null };

      const worker = new Worker(__filename, {
        workerData: { n, start, end, buffers }
      });

      state.worker = worker;

      worker.on('message', () => {
        const done = state.done;
        state.done = null;
        done();
      });

      worker.on('error', (err) => {
        throw err;
      });

      workers.push(worker);
      states.push(state);
    }

    function runPhase(op, inputIndex, outputIndex) {
      let remaining = states.length;

      return new Promise((resolve) => {
        for (const state of states) {
          state.done = () => {
            remaining--;
            if (remaining === 0) resolve();
          };
          state.worker.postMessage([op, inputIndex, outputIndex]);
        }
      });
    }

    async function multiplyAtAvParallel(inputIndex, outputIndex) {
      await runPhase(0, inputIndex, 2);
      await runPhase(1, 2, outputIndex);
    }

    for (let i = 0; i < 10; i++) {
      await multiplyAtAvParallel(0, 1);
      await multiplyAtAvParallel(1, 0);
    }

    let vBv = 0.0;
    let vv = 0.0;

    for (let i = 0; i < n; i++) {
      vBv += u[i] * v[i];
      vv += v[i] * v[i];
    }

    for (const worker of workers) {
      worker.terminate();
    }

    return Math.sqrt(vBv / vv);
  }

  (async () => {
    let result;

    if (n >= 1500) {
      result = await runParallel(n);
    } else {
      result = runSingle(n);
    }

    process.stdout.write(result.toFixed(9) + '\n');
  })();
}
